export const tenderBidsSubmit = async (tenderId: string,
    tenderBidsSubmitBody: TenderBidsSubmitBody, options?: Parameters<typeof apiFetch>[1]): Promise<SupplierBid> => {
    const formData = new FormData();
formData.append(`bid`, tenderBidsSubmitBody.bid);
if(tenderBidsSubmitBody['files[legal_information][registration_certificate]'] !== undefined) {
 formData.append(`files[legal_information][registration_certificate]`, tenderBidsSubmitBody['files[legal_information][registration_certificate]']);
 }
if(tenderBidsSubmitBody['languages[legal_information][registration_certificate]'] !== undefined) {
 formData.append(`languages[legal_information][registration_certificate]`, tenderBidsSubmitBody['languages[legal_information][registration_certificate]']);
 }
if(tenderBidsSubmitBody['files[technical_offer][technical_proposal]'] !== undefined) {
 formData.append(`files[technical_offer][technical_proposal]`, tenderBidsSubmitBody['files[technical_offer][technical_proposal]']);
 }
if(tenderBidsSubmitBody['languages[technical_offer][technical_proposal]'] !== undefined) {
 formData.append(`languages[technical_offer][technical_proposal]`, tenderBidsSubmitBody['languages[technical_offer][technical_proposal]']);
 }
if(tenderBidsSubmitBody['files[financial_offer][financial_proposal]'] !== undefined) {
 formData.append(`files[financial_offer][financial_proposal]`, tenderBidsSubmitBody['files[financial_offer][financial_proposal]']);
 }
if(tenderBidsSubmitBody['languages[financial_offer][financial_proposal]'] !== undefined) {
 formData.append(`languages[financial_offer][financial_proposal]`, tenderBidsSubmitBody['languages[financial_offer][financial_proposal]']);
 }

  return apiFetch<SupplierBid>(getTenderBidsSubmitUrl(tenderId),
  {
    ...options,
    method: 'POST'
    ,
    body: formData
  }
);}





